css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent !important;
}

.alarm-widget {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 89px 60px 18px;

  display: grid;
  grid-template-rows: minmax(0, 1fr);
  gap: 0;

  container-type: size;
  background: transparent;
  color: #223441;

  font-family:
    Bahnschrift,
    "Segoe UI",
    Arial,
    sans-serif;

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.alarm-board {
  /*
   * Cada cuadro crece 16px respecto de la versión anterior:
   * 8px hacia la izquierda y 8px hacia la derecha.
   */
  --slot-width:
    clamp(116px, calc(9.6cqw + 30px), 200px);

  /*
   * La separación uniforme entre columnas aumenta 20px.
   */
  --column-gap:
    clamp(36px, calc(1.45cqw + 20px), 44px);

  display: grid;
  grid-template-columns:
    max-content
    repeat(3, var(--slot-width));
  grid-template-rows:
    54px
    repeat(8, clamp(40px, 4.6cqw, 49px));

  column-gap: var(--column-gap);
  row-gap: 10px;

  width: max-content;
  max-width: 100%;
  margin: 0 auto;
  height: 100%;
  min-height: 0;
  align-content: space-between;
}

/* Todas las filas comparten las mismas cuatro columnas. */
.alarm-header,
.alarm-rows,
.alarm-row {
  display: contents;
}

.alarm-heading {
  display: flex;
  align-items: flex-end;
  justify-content: center;

  min-width: 0;
  padding: 0 2px 6px;

  color: #0a638f;
  font-size: clamp(17px, 1.4cqw, 23px);
  font-weight: 700;
  line-height: 1.12;
  text-align: center;
}

.alarm-label {
  align-self: center;

  color: #223441;
  font-size: clamp(15px, 1.35cqw, 20px);
  font-weight: 700;
  line-height: 1.12;
  white-space: nowrap;
}

.alarm-cell {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 100%;
}

/* Recuadro visual vacío. */
.alarm-slot {
  width: 100%;
  height: clamp(26px, 3cqw, 38px);

  border: 1px solid #687984;
  border-radius: 2px;
  background: linear-gradient(180deg, #e3e5e7, #d7d8db);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    inset 0 -1px 2px rgba(47, 60, 69, 0.09),
    0 1px 2px rgba(32, 48, 61, 0.12);
}

.alarm-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 4px;

  color: #20323b;
  font-size: clamp(16px, 1.25cqw, 20px);
  font-weight: 700;
  font-style: italic;
  white-space: nowrap;
}
/* Solo texto: encabezado transparente con la tipografía del ejemplo de recetas. */
.screen-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 70px;
  min-width: 0;
  padding: 14px 30px 0;
  overflow: hidden;
  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  user-select: none;
}

.screen-title {
  margin: 0;
  padding: 0;
  color: #0E5B67;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.screen-subtitle {
  margin: 5px 0 0;
  padding: 0;
  color: #728DA5;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
}

