"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 3 / HABILITACIÓN DE PARADAS";
  const DEFAULT_SUBTITLE = "Habilitación de alarmas, paradas de línea y rutinas de autocorrección";

  let headerTitle = null;
  let headerSubtitle = null;

  /* NOMBRE: Título//Subtítulo. Con Título// se oculta el subtítulo.
   * Sin NOMBRE se muestran ambos textos predeterminados.
   * Sin separador se personaliza solo el título.
   */
  function updateHeader(widget) {
    if (!headerTitle || !headerSubtitle) return;
    const name = widget && typeof widget.name === "string"
      ? widget.name.trim() : "";
    const separator = name.indexOf("//");
    const titleText = separator >= 0 ? name.slice(0, separator).trim() : name;
    const subtitleText = separator >= 0
      ? name.slice(separator + 2).trim() : DEFAULT_SUBTITLE;

    headerTitle.textContent = titleText || DEFAULT_TITLE;
    headerSubtitle.textContent = subtitleText;
    headerSubtitle.hidden = subtitleText === "";
    fitHeader();
  }

  function fitHeader() {
    [[headerTitle, 28], [headerSubtitle, 14]].forEach(function (entry) {
      const element = entry[0];
      if (!element || element.hidden) return;
      const size = entry[1];
      element.style.fontSize = size + "px";
      const available = element.clientWidth;
      if (available > 0 && element.scrollWidth > available) {
        element.style.fontSize = (size * available / element.scrollWidth) + "px";
      }
    });
  }

  let latestWidget = null;
  let headerObserver = null;


  const LABELS = [
    "Temperatura de Pre-Estiramiento",
    "Temperatura de Estiramiento",
    "Temperatura de Cuba de Preparación",
    "Temperatura Secador Zona 1",
    "Temperatura Secador Zona 2",
    "Temperatura Secador Zona 3",
    "Temperatura Secador Zona 4",
    "Temperatura Secador Zona 5"
  ];

  function make(tag, className, parent, text) {
    const element = document.createElement(tag);
    element.className = className;

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function makeRow(label, parent) {
    const row = make("div", "alarm-row", parent);

    make("div", "alarm-label", row, label);

    for (let column = 0; column < 3; column += 1) {
      const cell = make("div", "alarm-cell", row);
      const slot = make("div", "alarm-slot", cell);
      slot.setAttribute("aria-hidden", "true");
    }
  }

  function buildWidget() {
    const rows = document.getElementById("alarm-rows");
    if (!rows) return;

    rows.replaceChildren();

    LABELS.forEach(function (label) {
      makeRow(label, rows);
    });

    headerTitle = document.querySelector(".screen-title");
    headerSubtitle = document.querySelector(".screen-subtitle");
    updateHeader(latestWidget || window.WIDGET || null);

    if (typeof ResizeObserver !== "undefined") {
      headerObserver = new ResizeObserver(fitHeader);
      headerObserver.observe(document.querySelector(".screen-header"));
    } else {
      window.addEventListener("resize", fitHeader);
    }
  }

  /* Widget visual: no recibe variables del PLC. */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      buildWidget,
      { once: true }
    );
  } else {
    buildWidget();
  }
})();
